function run() {
	let output = "";

	let header = "{{itensMenuDinamico@header}}";
	let body = "{{itensMenuDinamico@body}}";
	let footer = "{{itensMenuDinamico@footer}}";


	if(header) output += `<b>${header}</b> \n \n`
	if(body) output += `${body} \n \n `
	if(footer) output += `<i>${footer}</i>`;

	return output;
}

function run(siteConsegnadoItemEscolhido) {
	let output = siteConsegnadoItemEscolhido.includes("value") ? JSON.parse(siteConsegnadoItemEscolhido) : {};

	if (!output.value) output = { value: siteConsegnadoItemEscolhido };

	return output;
}

function run(contadorPagina, itemEscolhido, itensFormatadoMenu) {
	try {
		itemEscolhido = JSON.parse(itemEscolhido);
		itensFormatadoMenu = JSON.parse(itensFormatadoMenu);
		contadorPagina = contadorPagina ? Number(contadorPagina) : 0;

		if (itemEscolhido.value.toLowerCase().includes("ver mais") || itensFormatadoMenu.some((opt) => opt.order === Number(itemEscolhido.value) && opt.text.toLowerCase().includes("ver mais"))) {
			contadorPagina += 1;
			return contadorPagina;
		}
		if (itemEscolhido.value.toLowerCase().includes("voltar") || itensFormatadoMenu.some((opt) => opt.order === Number(itemEscolhido.value) && opt.text.toLowerCase().includes("voltar"))) {
			contadorPagina -= 1;
			return contadorPagina;			
		}
		return	-1;
	} catch (e) {
		return 0;
	}
}

function run(itemEscolhido, itensFaqs, itensFormatadoMenu) {
	try {
		itensFaqs = JSON.parse(itensFaqs);
		let itemsTotal = [];
		itensFaqs.map((item) => { itemsTotal = [].concat(itemsTotal, item.rows) });

		itemEscolhido = JSON.parse(itemEscolhido);
		itensFormatadoMenu = JSON.parse(itensFormatadoMenu);

		let itensFormatadoMenuTotal = [];
		itensFormatadoMenu.map((item) => { itensFormatadoMenuTotal = [].concat(itensFormatadoMenuTotal, item) });

		const opcoes = [
			{ title: "Ver mais opções" },
			{ title: "Voltar" },
		]

		return itemsTotal.concat(opcoes).find((conv, index) => 
			conv.title.toString().toUpperCase() === itemEscolhido.value.toString().toUpperCase() ||
			conv.title.toString().toUpperCase().includes(itemEscolhido.value.toString().toUpperCase()) ||
			itemEscolhido.value.toString().toUpperCase().includes(conv.title.toString().toUpperCase()) ||
			itensFormatadoMenuTotal.some((itemMenu) => 
				itemMenu.order === Number(itemEscolhido.value) && (
					conv.title.toString().toUpperCase() === itemMenu.text.toString().toUpperCase() ||
					conv.title.toString().toUpperCase().includes(itemMenu.text.toString().toUpperCase()) ||
					itemMenu.text.toString().toUpperCase().includes(conv.title.toString().toUpperCase())
				)
			)
		) || false;
	} catch (e) {
		return false;
	}
}

function run(page, conveniosFormatados) {
	try {
		conveniosFormatados = JSON.parse(conveniosFormatados);
		let counter = conveniosFormatados[page].length;

		const opcoesFormatadas = conveniosFormatados[page].map((opcao, index) => ({
			order: index + 1,
			text:	opcao,
			type: "application/json",
			value: { value: opcao }
		}));

		if (conveniosFormatados[Number(page) + 1]) {
			opcoesFormatadas.push({
				order: counter + 1,
				text:	'Ver mais opções',
				type: "application/json",
		        value:{ value: "Ver mais opções" }
			})
			counter += 1;
		}

		if (Number(page) !== 0) opcoesFormatadas.push({
			order: counter + 1,
			text:	"Voltar",
			type: "application/json",
			value:{ value: "Voltar" },
		});

		return opcoesFormatadas;		
	} catch (err) {
		return 'Erro ao formatar menu de sites de consignacão';
	}
}

function formatterTitle(str) {
	let titleStyle = "{{itensMenuDinamico@titleStyle}}";

	if(!titleStyle) titleStyle = "none";
	titleStyle = titleStyle.toLowerCase();

	switch (titleStyle) {
		case "capitalize": {
			return str.split(" ").map((str2) => str2.charAt(0).toUpperCase() + str2.slice(1).toLowerCase()).join(" ");
		}
		case "lowercase": {
			return str.toLowerCase();
		}
		case "uppercase": {
			return str.toUpperCase();
		}
		case "normal": {
			return str.charAt(0).toUpperCase() + str.slice(1).toLowerCase();
		}
		default: {
			return str;
		}
	}

}

function run(items) {
	try {
		items = JSON.parse(items);
		let itemsFiltered = [];

		Object.values(items).map((item) => { itemsFiltered = [].concat(itemsFiltered, item.rows) });

		if (itemsFiltered.length === 0) return false;

		const itemsMenu = [];
		let page = [];

		itemsFiltered.forEach((info, index, array) => {
			const item = formatterTitle(info.title.toString());
			page.push(item)
			if (((index + 1) % 8 === 0 && array.length > 10) || index === itemsFiltered.length - 1) {
				itemsMenu.push(page);
				page = [];
			}
		})

		return itemsMenu;
	} catch (e) {
		return false;
	}
}

