		let totalDeItensMenu = 0;
		itensFormatados[page].map((item) => { totalDeItensMenu += item.rows.length });
		let counter = totalDeItensMenu;

		const opcoesFormatadas = itensFormatados[page].map((item, indexMenu, array) => ({
			...item,
			rows: item.rows.map((opcao, index) => {
				const output = ({
					id: ((array[indexMenu - 1] ? array[indexMenu - 1].rows.length : 0) + (index + 1)).toString(),
				})

				if(opcao.title) output.title = opcao.title;
				if(opcao.description) output.description = opcao.description;
				return output;
			})
		}));

		let navigation = "{{itensMenuDinamico@navigation}}";

		if(!navigation) navigation = "Navegação"

		if (itensFormatados[Number(page) + 1]) {
			const indexOfOutros = opcoesFormatadas.findIndex((item) => item.title === navigation)
			if (opcoesFormatadas[indexOfOutros]){
				opcoesFormatadas[indexOfOutros].rows.push({
					id: (counter + 1).toString(),
					title:	'Ver mais opções',
				})
			}  else {
				opcoesFormatadas.push({
					title: navigation,
					rows: [{
					id: (counter + 1).toString(),
